 auto save=[&](String filename){FileOutputStream out(File::getCurrentWorkingDirectory().getChildFile(filename));out.setPosition(0);out.truncate();PNGImageFormat().writeImageToStream(editor->createComponentSnapshot(editor->getLocalBounds()),out);};save("Nexum-Master.png");packs->onClick();int actions=0;for(auto* child:browser->getChildren())if(child->getComponentID()=="load-preset-file"||child->getComponentID()=="asset-folder"||child->getComponentID()=="import-info")if(child->isVisible())++actions;if(actions!=2||!browser->isVisible()||!panel->isVisible()){std::cerr<<"MASTER FAIL: visible Library load/assets actions or global master\n";return 265;}save("Nexum-Packs-Master.png");std::cout<<"PASS: final-output stereo meters, channel isolation, calibrated peaks/release, master gain binding, global header and Library load/assets actions and retained import/info callbacks.\n";return 0;
